{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Diphemanil methylsulphate, a quaternary ammonium anticholinergic, showed very low oral bioavailability in healthy subjects after a 250 mg oral dose, directly supporting low F for the query's permanent positive charge.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "DX-9065, a strongly basic amidine-containing drug, had human oral bioavailability of only 2–3%, attributed to poor absorption caused by strong basic groups; this supports low F for a charged, poorly absorbed query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Acamprosate is poorly absorbed with an average oral bioavailability of about 11% under fasting conditions, supporting low F for a polar, poorly permeable drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Lercanidipine has an absolute oral bioavailability of about 10% in fed hypertensive patients due to extensive first-pass metabolism, supporting low F for a lipophilic drug with high presystemic clearance.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Selegiline exhibits low oral bioavailability in healthy volunteers, being rapidly absorbed and extensively metabolized, supporting low F for a drug with substantial first-pass liability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Phenylephrine has poor oral bioavailability in healthy volunteers despite intravenous potency, supporting low F for a polar drug with limited oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "A related compound was predicted to have 0% oral bioavailability in humans based on in vivo animal data, supporting low F for the query's structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Propafenone, a basic drug with extensive presystemic metabolism, showed mean oral bioavailability of 18.6% ± 8.8% (range 5–31%), mostly below the 20% threshold, supporting low F for a related basic drug with first-pass metabolism.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a quaternary ammonium tropane ester with a permanent positive charge, a major absorption liability. The most direct analogue, diphemanil methylsulphate, shows very low oral bioavailability. Additional strongly basic or poorly absorbed drugs (DX-9065, acamprosate, lercanidipine, selegiline, phenylephrine) and a predicted 0% human F for a related compound all support F < 20%. The physicochemical prior is mixed, but the experimental evidence strongly favors low oral bioavailability.",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability measurement exists for the query molecule.",
    "No data on intestinal permeability, efflux transporter involvement, or biliary excretion are available for the query.",
    "Propafenone data are variable and include some values above 20%, though the mean is below threshold.",
    "Quaternary ammonium compounds can occasionally show higher absorption, so direct human data would reduce residual uncertainty."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C12"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "quaternary ammonium analogue"
    },
    {
      "applicability": "high",
      "card_ids": ["C02"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "strongly basic amidine"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C13", "C07"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "poorly absorbed polar drugs"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C33", "C40", "C19"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "first-pass metabolism drugs"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C42"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "predicted human oral bioavailability"
    }
  ],
  "revision_action": "initial"
}

